-- 03_starting_texts.sql
-- The starting texts for every topic in listening_topics (18) and reading_topics (21), written and
-- checked by hand, with English translations and 4 questions each. Students get them instantly,
-- without spending an AI use. Run it after 02_topics.sql.
-- Safe to run more than once: a text that is already there is not added again. It removes nothing.

insert into "French-schema".library_texts (level, subject, kind, title, fr, en, questions, topic, skill, created_by)
select $v$A1$v$, $v$Salutations & Contacts$v$, $v$Dialogue$v$, $v$À l'accueil de l'école de langues$v$,
$fr$— Bonjour ! Bienvenue à l'école. Comment vous appelez-vous ?
— Bonjour. Je m'appelle Karim Belkacem.
— Vous pouvez épeler votre nom de famille, s'il vous plaît ?
— Oui : B-E-L-K-A-C-E-M.
— Merci. Et vous avez quel âge ?
— J'ai vingt-huit ans.
— Vous êtes de quelle nationalité ?
— Je suis algérien, mais j'habite à Lyon depuis un an.
— Très bien. Votre adresse e-mail ?
— Karim point B, arobase mail point F R. Karim, avec un K.
— Parfait. Votre cours commence lundi à neuf heures, salle douze.
— Merci beaucoup. Bonne journée !$fr$,
$en$— Hello! Welcome to the school. What is your name?
— Hello. My name is Karim Belkacem.
— Can you spell your surname, please?
— Yes: B-E-L-K-A-C-E-M.
— Thank you. And how old are you?
— I'm twenty-eight.
— What nationality are you?
— I'm Algerian, but I've been living in Lyon for a year.
— Very good. Your email address?
— Karim dot B, at mail dot F R. Karim, with a K.
— Perfect. Your class starts on Monday at nine o'clock, room twelve.
— Thank you very much. Have a nice day!$en$,
$q$[{"q": "How old is Karim?", "options": ["28", "18", "38"], "answer": 0, "why": "\"J'ai vingt-huit ans\" = I am twenty-eight."}, {"q": "Where does Karim live?", "options": ["In Lyon", "In Algiers", "In Paris"], "answer": 0, "why": "\"J'habite à Lyon depuis un an.\""}, {"q": "How does he spell his first name?", "options": ["With a K", "With a C", "With a Q"], "answer": 0, "why": "\"Karim, avec un K.\""}, {"q": "When does his class start?", "options": ["Monday at 9 o'clock", "Monday at 12 o'clock", "Thursday at 9 o'clock"], "answer": 0, "why": "\"Votre cours commence lundi à neuf heures, salle douze.\" Twelve is the room number."}]$q$::jsonb, $v$Se présenter et épeler son nom$v$, $v$listening$v$, null
where not exists (select 1 from "French-schema".library_texts where skill = $v$listening$v$ and topic = $v$Se présenter et épeler son nom$v$ and title = $v$À l'accueil de l'école de langues$v$);

insert into "French-schema".library_texts (level, subject, kind, title, fr, en, questions, topic, skill, created_by)
select $v$A1$v$, $v$Vie Quotidienne$v$, $v$Dialogue$v$, $v$À la boulangerie$v$,
$fr$— Bonjour madame !
— Bonjour monsieur. Je voudrais une baguette et deux croissants, s'il vous plaît.
— Voilà. Et avec ceci ?
— Un pain au chocolat, aussi. C'est combien ?
— Alors, la baguette, c'est un euro vingt. Les croissants, un euro dix chacun, et le pain au chocolat, un euro trente. Ça fait quatre euros soixante-dix.
— Voilà cinq euros.
— Merci. Je vous rends trente centimes.
— Vous êtes ouverts dimanche ?
— Oui, le dimanche, nous sommes ouverts de sept heures à treize heures.
— Parfait. Merci, au revoir !$fr$,
$en$— Hello madam!
— Hello sir. I'd like a baguette and two croissants, please.
— Here you are. Anything else?
— A pain au chocolat, too. How much is it?
— So, the baguette is one euro twenty. The croissants are one euro ten each, and the pain au chocolat is one euro thirty. That comes to four euros seventy.
— Here's five euros.
— Thank you. Here are thirty cents change.
— Are you open on Sunday?
— Yes, on Sundays we are open from seven a.m. to one p.m.
— Perfect. Thank you, goodbye!$en$,
$q$[{"q": "How many croissants does the customer buy?", "options": ["Two", "One", "Three"], "answer": 0, "why": "\"Une baguette et deux croissants.\""}, {"q": "How much is the baguette?", "options": ["€1.20", "€1.10", "€1.30"], "answer": 0, "why": "\"La baguette, c'est un euro vingt.\""}, {"q": "How much change does she get?", "options": ["30 cents", "70 cents", "€1.30"], "answer": 0, "why": "She pays €5 for €4.70: \"Je vous rends trente centimes.\""}, {"q": "When does the bakery close on Sunday?", "options": ["At 1 p.m.", "At 7 a.m.", "At 3 p.m."], "answer": 0, "why": "\"De sept heures à treize heures\": 13h is 1 p.m."}]$q$::jsonb, $v$Comprendre les nombres, les prix et les heures$v$, $v$listening$v$, null
where not exists (select 1 from "French-schema".library_texts where skill = $v$listening$v$ and topic = $v$Comprendre les nombres, les prix et les heures$v$ and title = $v$À la boulangerie$v$);

insert into "French-schema".library_texts (level, subject, kind, title, fr, en, questions, topic, skill, created_by)
select $v$A1$v$, $v$Annonces Publiques$v$, $v$Announcement$v$, $v$Annonce au supermarché$v$,
$fr$Mesdames et messieurs, bonjour et bienvenue au supermarché Bon Prix !
Aujourd'hui, au rayon fruits et légumes, les fraises sont en promotion : deux euros la barquette.
Au rayon boulangerie, une baguette achetée, une baguette offerte, jusqu'à midi.
Nous vous rappelons que les toilettes sont au fond du magasin, à côté de la sortie.
Attention : le parking ferme à vingt heures ce soir.
Le magasin ferme à vingt heures trente.
Merci et bonnes courses !$fr$,
$en$Ladies and gentlemen, hello and welcome to the Bon Prix supermarket!
Today, in the fruit and vegetable section, strawberries are on special offer: two euros a punnet.
In the bakery section, buy one baguette, get one free, until noon.
We remind you that the toilets are at the back of the shop, next to the exit.
Please note: the car park closes at eight p.m. this evening.
The shop closes at eight thirty p.m.
Thank you and happy shopping!$en$,
$q$[{"q": "What is on special offer in the fruit section?", "options": ["Strawberries", "Apples", "Tomatoes"], "answer": 0, "why": "\"Les fraises sont en promotion.\""}, {"q": "Until when is the baguette offer?", "options": ["Until noon", "Until 8 p.m.", "All day"], "answer": 0, "why": "\"Jusqu'à midi.\""}, {"q": "Where are the toilets?", "options": ["At the back, next to the exit", "Next to the bakery", "In the car park"], "answer": 0, "why": "\"Au fond du magasin, à côté de la sortie.\""}, {"q": "What closes at 8 p.m.?", "options": ["The car park", "The shop", "The bakery"], "answer": 0, "why": "\"Le parking ferme à vingt heures.\" The shop closes at 8.30."}]$q$::jsonb, $v$Annonces simples dans un magasin ou supermarché$v$, $v$listening$v$, null
where not exists (select 1 from "French-schema".library_texts where skill = $v$listening$v$ and topic = $v$Annonces simples dans un magasin ou supermarché$v$ and title = $v$Annonce au supermarché$v$);

